    print(str(r)[:1800]);print('----')

r=await web_search({"query":"Uber Arena Berlin annual visitors per year events"})
for x in r[:6]:
    print(x['url']);
    import re
    c=x['content']
    for m in re.finditer(r'[^.]*(visitors|Besucher)[^.]*\.',c):
        print('  ',m.group(0)[:250]);break

qs=["TikTok Germany Berlin Osthafenspeicher Stralauer Allee employees","Zalando Headquarter Tamara-Danz-Straße Berlin Mitarbeiter Stream Tower"]
for q in qs:
    r=await web_search({"query":q})
    for x in r[:4]:
        print(x['url']);
        import re
        c=x['content']
        for m in re.finditer(r'[^.]*\b(employees|Mitarbeit|Beschäftigte)[^.]*\.',c):
            print('  ',m.group(0)[:200]);break

for q in qs:
    r=await web_search({"query":q})
    print(type(r), str(r)[:300])

import json,re
for q in qs:
    r=json.loads(await web_search({"query":q}))
    for x in r[:5]:
        print(x['url'])
        for m in re.finditer(r'[^.\n]*\b(employees|Mitarbeitende|Mitarbeiter|Beschäftigte|Arbeitsplätze|workplaces)[^.\n]*',x['content']):
            print('  ',m.group(0)[:250])
            break

